<script setup lang="ts">
import MarkdownIt from 'markdown-it'
import { useVirtualizer } from '@tanstack/vue-virtual'
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import questionIndex from '../generated/question-bank/index.json?question-bank-schema=2'
import './question-bank-drawer.css'

type Role = 'hardware' | 'embedded-linux' | 'embedded-mcu' | 'fpga'
type Classification = 'GENERAL' | 'GENERALIZABLE' | 'PROJECT' | 'BEHAVIORAL'
interface QuestionSource { rawQuestion:string; classification:Classification; company:string; role:string; rounds:string[]; year:number|null; location:string|null; platform:string; url:string|null; author:string; sourceType:string; transcription:string }
interface Question { id:string; question:string; roles:Role[]; companies:string[]; topic:string; tags:string[]; answerViews:Role[]; sources:QuestionSource[]; shard:number }
const labels: Record<Role, string> = { hardware:'硬件工程师', 'embedded-linux':'嵌入式 Linux', 'embedded-mcu':'嵌入式 MCU', fpga:'FPGA 工程师' }
const classificationLabels:Record<Classification,string>={GENERAL:'通用原题标准化',GENERALIZABLE:'由项目相关原题抽象',PROJECT:'项目相关题',BEHAVIORAL:'行为题'}
const roleKeys = Object.keys(labels) as Role[]
const topicOrder = ['电源与硬件设计', '高速接口与 FPGA', 'MCU 与嵌入式软件', '通信与网络', '采集与控制', '测试与系统工程']
const questions=ref<Question[]>([]), ids=ref<string[]>([]), query=ref(''), roles=ref<Role[]>([]), company=ref<string|null>(null), topic=ref<string|null>(null), tag=ref<string|null>(null), loading=ref(true), message=ref('')
const active=ref<Question|null>(null), answer=ref<Record<Role,string>|null>(null), answerShown=ref(false), answerLoading=ref(false), answerError=ref(''), view=ref<Role|null>(null), scroll=ref<HTMLElement|null>(null), panel=ref<HTMLElement|null>(null), opener=ref<HTMLElement|null>(null), scrollTop=ref(0), viewportHeight=ref(728), page=ref(1), pageSize=ref(12), tagsExpanded=ref(false), topicsExpanded=ref(false)
let worker:Worker|undefined, timer:ReturnType<typeof setTimeout>, request=0
const cache=new Map<number,Record<string,{answers:Record<Role,string>}>>(); const lookup=computed(()=>new Map(questions.value.map(q=>[q.id,q]))); const items=computed(()=>ids.value.map(id=>lookup.value.get(id)).filter(Boolean) as Question[]); const normalizedPageSize=computed(()=>Math.min(100,Math.max(1,Number(pageSize.value)||12))); const pageCount=computed(()=>Math.max(1,Math.ceil(items.value.length/normalizedPageSize.value))); const pagedItems=computed(()=>items.value.slice((page.value-1)*normalizedPageSize.value,page.value*normalizedPageSize.value)); const companies=computed(()=>[...new Set(questions.value.flatMap(q=>q.companies))]); const topics=computed(()=>topicOrder.filter(x=>questions.value.some(q=>q.topic===x))); const baseVisibleTopics=computed(()=>topicsExpanded.value?topics.value:topics.value.slice(0,4)); const visibleTopics=computed(()=>{const base=baseVisibleTopics.value;if(topic.value&&!base.includes(topic.value))return [...base,topic.value];return base}); const remainingTopicCount=computed(()=>Math.max(0,topics.value.length-(topic.value&&!topics.value.slice(0,4).includes(topic.value)?5:4))); const tagFrequency=(source:Question[])=>{const counts=new Map<string,number>();source.forEach(q=>q.tags.forEach(x=>counts.set(x,(counts.get(x)||0)+1)));return counts}; const sortTags=(counts:Map<string,number>)=>[...counts].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'zh-CN')).map(([x])=>x); const allTags=computed(()=>sortTags(tagFrequency(questions.value))); const upstreamQuestions=computed(()=>questions.value.filter(q=>(!roles.value.length||roles.value.some(r=>q.roles.includes(r)))&&(!company.value||q.companies.includes(company.value))&&(!topic.value||q.topic===topic.value))); const availableTagCounts=computed(()=>{const counts=tagFrequency(upstreamQuestions.value);if(tag.value&&!counts.has(tag.value))counts.set(tag.value,0);return counts}); const availableTags=computed(()=>sortTags(availableTagCounts.value)); const availableTagSet=computed(()=>new Set(tagFrequency(upstreamQuestions.value).keys())); const collapsedTags=computed(()=>availableTags.value.slice(0,6)); const visibleTags=computed(()=>{if(tagsExpanded.value)return availableTags.value;const base=collapsedTags.value;if(tag.value&&availableTags.value.includes(tag.value)&&!base.includes(tag.value))return [...base,tag.value];return base}); const remainingTagCount=computed(()=>Math.max(0,availableTags.value.length-(tag.value&&availableTags.value.includes(tag.value)&&!collapsedTags.value.includes(tag.value)?collapsedTags.value.length+1:collapsedTags.value.length))); const totalTags=computed(()=>allTags.value.length); const activeFilterRoles=computed(()=>roles.value); const activeFilterQuery=computed(()=>query.value.trim()); const hasActiveFilters=computed(()=>Boolean(activeFilterQuery.value||roles.value.length||company.value||topic.value||tag.value)); const views=computed(()=>active.value?.answerViews||[]); const html=ref('')
const virtualizer=useVirtualizer({ count:()=>pagedItems.value.length, getScrollElement:()=>scroll.value, estimateSize:()=>112, overscan:3 }); const virtualItems=computed(()=>virtualizer.value.getVirtualItems()); const safeVirtualItems=computed(()=>virtualItems.value.filter(row=>row&&pagedItems.value[row.index])); const totalSize=computed(()=>virtualizer.value.getTotalSize())
function search(){ if(!worker){const term=query.value.trim().toLocaleLowerCase();ids.value=questions.value.filter(q=>{const text=[q.question,...q.roles.map(r=>labels[r]),...q.companies,q.topic,...q.tags].join(' ').toLocaleLowerCase();return(!term||text.includes(term))&&(!roles.value.length||roles.value.some(r=>q.roles.includes(r)))&&(!company.value||q.companies.includes(company.value))&&(!topic.value||q.topic===topic.value)&&(!tag.value||q.tags.includes(tag.value))}).map(q=>q.id);return} worker.postMessage({type:'search',requestId:++request,query:query.value,roles:[...roles.value],company:company.value,topic:topic.value,tag:tag.value}) }
function toggle(role:Role){ const next=roles.value.includes(role)?roles.value.filter(x=>x!==role):[...roles.value,role]; roles.value=next.length===roleKeys.length?[]:next }
function selectAllRoles(){ roles.value=[] }
function toggleCompany(name:string){ company.value=company.value===name?null:name }
function selectAllCompany(){ company.value=null }
function toggleTopic(name:string){ topic.value=topic.value===name?null:name }
function selectAllTopic(){ topic.value=null }
function toggleTag(name:string){ tag.value=tag.value===name?null:name }
function selectAllTag(){ tag.value=null }
function normalizeRoles(values:string[]):Role[]{ const next=[...new Set(values.filter((value):value is Role=>roleKeys.includes(value as Role)))]; return next.length===roleKeys.length?[]:next }
function applyUrlState(){ const params=new URLSearchParams(window.location.search); roles.value=normalizeRoles((params.get('role')||'').split(',').filter(Boolean)); company.value=params.get('company')||null; topic.value=params.get('topic')||null; tag.value=params.get('tag')||null; query.value=params.get('q')||'' }
function syncUrl(){ if(typeof window==='undefined')return; const url=new URL(window.location.href); if(roles.value.length)url.searchParams.set('role',roles.value.join(','));else url.searchParams.delete('role'); if(company.value)url.searchParams.set('company',company.value);else url.searchParams.delete('company'); if(topic.value)url.searchParams.set('topic',topic.value);else url.searchParams.delete('topic'); if(tag.value)url.searchParams.set('tag',tag.value);else url.searchParams.delete('tag'); const keyword=query.value.trim(); if(keyword)url.searchParams.set('q',keyword);else url.searchParams.delete('q'); window.history.replaceState(window.history.state,'',`${url.pathname}${url.search}${url.hash}`); window.dispatchEvent(new CustomEvent('question-bank-filter-change')) }
function measureCards(){
  if(typeof document==='undefined')return;
  const cards=[...document.querySelectorAll<HTMLElement>('.bank .list .card')];
  const rows=safeVirtualItems.value;
  cards.forEach((card,index)=>{
    const row=rows[index];
    if(!row)return;
    card.dataset.index=String(row.index);
    virtualizer.value.measureElement(card);
  });
}
function scrollToQuestionList(behavior:ScrollBehavior='smooth'){ if(typeof window==='undefined')return; nextTick(()=>{const target=document.querySelector('.bank .count');if(!target)return;const navHeight=Number.parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--vp-nav-height'))||64;const top=target.getBoundingClientRect().top+window.scrollY-navHeight-16;window.scrollTo({top:Math.max(0,top),behavior}) }) }
function clear(){ query.value='';roles.value=[];company.value=null;topic.value=null;tag.value=null;syncUrl() }
function open(q:Question,e:MouseEvent){opener.value=e.currentTarget as HTMLElement;active.value=q;answer.value=null;answerError.value='';answerShown.value=false;view.value=roles.value.find(r=>q.answerViews.includes(r))||q.answerViews[0];nextTick(()=>panel.value?.focus())}
async function renderAnswer(){const value=answer.value?.[view.value||views.value[0]];if(!value)return;const renderer=new MarkdownIt({html:false,linkify:true,breaks:true});try{const {default:mathjax3}=await import('markdown-it-mathjax3');html.value=renderer.use(mathjax3).render(value)}catch{html.value=renderer.render(value)}}
async function show(){if(!active.value)return;answerShown.value=true;answerLoading.value=true;answerError.value='';try{let data=cache.get(active.value.shard);if(!data){const part=String(active.value.shard).padStart(2,'0');data=((await import(`../generated/question-bank/details-${part}.json?question-bank-answer-schema=3`)).default as {questions:Record<string,{answers:Record<Role,string>}>}).questions;cache.set(active.value.shard,data)}const detail=data[active.value.id];if(!detail)throw new Error(`Missing question detail: ${active.value.id}`);answer.value=detail.answers;await renderAnswer()}catch{answer.value=null;html.value='';answerError.value='答案数据加载失败，请刷新页面后重试。'}finally{answerLoading.value=false}}
function close(){active.value=null;answer.value=null;answerError.value='';nextTick(()=>opener.value?.focus())}
function focusablePanelElements(){return panel.value?[...panel.value.querySelectorAll<HTMLElement>('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')].filter(element=>!element.hasAttribute('disabled')&&element.getClientRects().length):[]}
function onKeydown(event:KeyboardEvent){if(!active.value)return;if(event.key==='Escape'){event.preventDefault();close();return}if(event.key!=='Tab')return;const elements=focusablePanelElements();if(!elements.length)return;const first=elements[0],last=elements[elements.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===panel.value)){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
onMounted(()=>{document.querySelector('style[data-question-bank-layout]')?.remove();const style=document.createElement('style');style.dataset.questionBankLayout='true';style.textContent='body:has(.bank) .content-container{max-width:1200px!important}.VPDoc:has(.bank){max-width:1200px!important;padding-bottom:0!important}.VPDoc:has(.bank) .container{display:block;max-width:none}.VPDoc:has(.bank) .aside{display:none}.VPDoc:has(.bank) .content{width:100%;max-width:none}.VPDoc:has(.bank) .bank{max-width:none;width:100%;padding-bottom:0!important}@media(max-width:960px){body:has(.bank) .content-container{max-width:100%!important}.VPDoc:has(.bank){max-width:100%!important}}';document.head.appendChild(style)})
watch([query,roles,company,topic,tag],()=>{syncUrl();page.value=1;clearTimeout(timer);scrollToQuestionList('auto');timer=setTimeout(search,120)});watch([roles,company,topic,questions],()=>{if(questions.value.length&&tag.value&&!availableTagSet.value.has(tag.value))tag.value=null});watch(active,x=>{document.body.style.overflow=x?'hidden':''});watch(answerShown,shown=>{nextTick(()=>{const title=document.querySelector<HTMLElement>('.recall-section>p');if(title)title.textContent=shown?'参考回答':'主动回忆'})});watch(view,()=>{if(answerShown.value)void renderAnswer()})
watch([items,pageSize],()=>{if(page.value>pageCount.value)page.value=pageCount.value});watch(pagedItems,()=>{virtualizer.value.setOptions({ ...virtualizer.value.options, count: pagedItems.value.length });nextTick(()=>{virtualizer.value.measure();measureCards()})});watch(page,()=>{scrollToQuestionList('smooth');nextTick(()=>{virtualizer.value.measure();measureCards()})})
watch(pageSize,()=>{if(pageSize.value>100)pageSize.value=100;if(pageSize.value<1||!Number.isFinite(pageSize.value))pageSize.value=12;page.value=1;scrollToQuestionList('smooth')})
onMounted(()=>{try{applyUrlState();questions.value=(questionIndex as {questions:Question[]}).questions;ids.value=questions.value.map(q=>q.id);worker=new Worker(new URL('../workers/question-search.worker.ts',import.meta.url),{type:'module'});worker.onmessage=e=>{if(e.data.type==='ready')search();if(e.data.type==='results'&&e.data.requestId===request)ids.value=e.data.ids};worker.onerror=()=>{worker?.terminate();worker=undefined;search()};worker.postMessage({type:'init',questions:questions.value.map(q=>({id:q.id,question:q.question,roles:[...q.roles],companies:[...q.companies],topic:q.topic,tags:[...q.tags]}))})}catch{message.value='题库初始化失败'}finally{loading.value=false}syncUrl();window.addEventListener('keydown',onKeydown);window.addEventListener('popstate',applyUrlState)});onUnmounted(()=>{worker?.terminate();window.removeEventListener('keydown',onKeydown);window.removeEventListener('popstate',applyUrlState);document.body.style.overflow=''})
</script>

<template><div class="bank-layout"><section class="bank"><header><p>CAREER / INTERVIEW LAB</p><h1>岗位题库</h1><span>先在脑内作答，再查看不同岗位视角的工程化解析。</span></header><div class="tools"><input v-model="query" aria-label="搜索题目、公司、岗位或技术标签" placeholder="搜索公司、岗位或技术标签，如 MIPI / 诺瓦星云"><div id="filters-role" class="filter-group" role="group" aria-label="岗位筛选"><b>岗位</b><div><button type="button" :aria-pressed="roles.length===0" :class="{on:roles.length===0}" @click="selectAllRoles">全部</button><button v-for="(name,key) in labels" :key="key" type="button" :aria-pressed="roles.includes(key)" :class="{on:roles.includes(key)}" @click="toggle(key)">{{name}}</button></div></div><div id="filters-topic" class="filter-group" role="group" aria-label="专题筛选"><b>专题</b><div :class="{expanded:topicsExpanded}"><button type="button" :aria-pressed="!topic" :class="{on:!topic}" @click="selectAllTopic">全部</button><button v-for="x in visibleTopics" :key="x" type="button" :aria-pressed="topic===x" :class="{on:topic===x}" @click="toggleTopic(x)">{{x}}</button><button v-if="remainingTopicCount>0" class="topic-more tag-more" type="button" :aria-expanded="topicsExpanded" @click="topicsExpanded=!topicsExpanded"><span v-if="!topicsExpanded">更多 {{remainingTopicCount}}</span><span v-else>收起</span></button></div></div><div id="filters-company" class="filter-group" role="group" aria-label="公司筛选"><b>公司</b><div><button type="button" :aria-pressed="!company" :class="{on:!company}" @click="selectAllCompany">全部</button><button v-for="name in companies" :key="name" type="button" :aria-pressed="company===name" :class="{on:company===name}" @click="toggleCompany(name)">{{name}}</button></div></div><div id="filters-tag" class="filter-group" role="group" aria-label="技术标签筛选"><b>技术标签</b><div><button type="button" :aria-pressed="!tag" :class="{on:!tag}" @click="selectAllTag">全部</button><button v-for="x in visibleTags" :key="x" type="button" :aria-pressed="tag===x" :class="{on:tag===x}" @click="toggleTag(x)">{{x}}</button><button v-if="remainingTagCount>0" class="tag-more" type="button" :aria-expanded="tagsExpanded" @click="tagsExpanded=!tagsExpanded"><span v-if="!tagsExpanded">更多 {{remainingTagCount}}</span><span v-else>收起</span></button></div></div></div><div class="count" aria-live="polite"><b>{{items.length}} 道题目 · 第 {{page}} / {{pageCount}} 页</b><label class="page-size" for="question-page-size">每页 <input id="question-page-size" aria-label="每页题目数量" v-model.number="pageSize" type="number" min="1" max="100" inputmode="numeric"> 题</label><button v-if="hasActiveFilters" type="button" @click="clear">清除筛选</button></div><div v-if="loading" class="empty">正在加载题库…</div><div v-else-if="items.length" ref="scroll" class="list"><div :style="{height:`${virtualizer.getTotalSize()}px`,position:'relative'}"><button v-for="row in safeVirtualItems" :key="pagedItems[row.index].id" class="card" :style="{transform:`translateY(${row.start}px)`}" @click="open(pagedItems[row.index],$event)"><i>{{String(row.index+1).padStart(2,'0')}}</i><strong>{{pagedItems[row.index].question}}<small><em v-for="r in pagedItems[row.index].roles" :key="r">{{labels[r]}}</em><em v-for="x in pagedItems[row.index].tags.slice(0,3)" :key="x">{{x}}</em></small></strong><span>↗</span></button></div></div><div v-else class="empty">{{message||'没有找到匹配题目。'}}</div><nav v-if="pageCount>1" class="pagination" aria-label="题目分页"><button :disabled="page===1" @click="page--">上一页</button><button v-for="n in pageCount" :key="n" :class="{on:page===n}" @click="page=n">{{n}}</button><button :disabled="page===pageCount" @click="page++">下一页</button></nav><Teleport to="body"><Transition name="drawer"><div v-if="active" class="mask" @click.self="close"><aside ref="panel" tabindex="-1" role="dialog" aria-modal="true" aria-labelledby="question-drawer-title"><button class="x" aria-label="关闭题目详情" @click="close">×</button><p>QUESTION / {{active.id}}</p><h2 id="question-drawer-title">{{active.question}}</h2><div class="question-context"><div><b>所属专题</b><span>{{active.topic}}</span></div><div><b>适用岗位</b><span>{{active.roles.map(role=>labels[role]).join('、')}}</span></div><div><b>技术标签</b><span>{{active.tags.join('、')}}</span></div><div><b>回答视角</b><span>{{active.answerViews.length}} 个</span></div></div><section class="source-section"><p>面试来源</p><article v-for="(source,index) in active.sources" :key="`${source.company}-${source.rawQuestion}`" class="source-card"><header><strong>来源 {{index+1}} · {{source.company}}</strong><em>{{classificationLabels[source.classification]}}</em></header><div class="source-facts"><span>{{source.role}}</span><span v-for="round in source.rounds" :key="round">{{round}}</span><span v-if="source.year">{{source.year}} 年</span><span v-if="source.location">{{source.location}}</span></div><b>原始问题</b><blockquote>{{source.rawQuestion}}</blockquote><footer><span>{{source.platform}} · {{source.author}} · {{source.sourceType}} · {{source.transcription}}</span><a v-if="source.url" :href="source.url" target="_blank" rel="noopener noreferrer">查看来源</a></footer></article></section><section class="recall-section"><p>主动回忆</p><template v-if="!answerShown"><span>先停 30 秒，在脑中组织你的工程回答：现象、根因、方案与验证。</span><button class="primary" @click="show">查看答案</button></template><span v-else-if="answerLoading">正在加载答案…</span><template v-else-if="answerError"><span class="answer-error">{{answerError}}</span><button class="primary" @click="show">重新加载答案</button></template><template v-else><div class="tabs"><button v-for="x in views" :key="x" :class="{on:view===x}" @click="view=x">{{labels[x]}}</button></div><article class="vp-doc" v-html="html"/></template></section></aside></div></Transition></Teleport></section><aside class="context-aside"><p>页面上下文</p><div v-if="hasActiveFilters" class="context-filter"><h2>当前筛选</h2><div class="context-filter-groups"><div v-if="activeFilterQuery" class="context-filter-group"><b>关键词</b><div class="context-tags"><span>{{activeFilterQuery}}</span></div></div><div v-if="activeFilterRoles.length" class="context-filter-group"><b>岗位</b><div class="context-tags"><span v-for="r in activeFilterRoles" :key="r">{{labels[r]}}</span></div></div><div v-if="topic" class="context-filter-group"><b>专题</b><div class="context-tags"><span>{{topic}}</span></div></div><div v-if="company" class="context-filter-group"><b>公司</b><div class="context-tags"><span>{{company}}</span></div></div><div v-if="tag" class="context-filter-group"><b>技术标签</b><div class="context-tags"><span>#{{tag}}</span></div></div></div></div><h2>题库概览</h2><dl><div><dt>题目</dt><dd>{{questions.length}}</dd></div><div><dt>岗位方向</dt><dd>{{Object.keys(labels).length}}</dd></div><div><dt>公司</dt><dd>{{companies.length}}</dd></div><div><dt>技术标签</dt><dd>{{totalTags}}</dd></div></dl></aside></div></template>

<style scoped>.bank{max-width:1040px;margin:auto;padding:20px 20px 64px}.bank header{padding:28px 0 26px;border-bottom:1px solid var(--vp-c-divider)}.bank header>p{margin:0 0 12px}header p,aside>p,section>p{color:#168260;font:700 .72rem var(--vp-font-family-mono);letter-spacing:.12em}.bank header h1{display:block;margin:0 0 12px;line-height:1.08;font-size:clamp(2.25rem,4vw,3.3rem);letter-spacing:-.06em}.bank header>span{display:block;color:var(--vp-c-text-2);line-height:1.6}.tools{display:grid;gap:6px;min-width:0;padding:12px 0 6px}.tools input{width:100%;min-width:0;box-sizing:border-box;height:50px;padding:0 15px;border:1px solid var(--vp-c-divider);border-radius:12px;background:var(--vp-c-bg-soft);color:var(--vp-c-text-1);font:inherit}.filter-group{display:flex!important;align-items:flex-start;gap:10px;min-width:0}.filter-group>b{flex:0 0 62px;padding-top:8px;color:var(--vp-c-text-2);font-size:.76rem}.filter-group>div{display:flex;flex:1 1 0;flex-wrap:wrap;gap:8px;min-width:0;max-width:100%}.tools div,.meta,.tabs{display:flex;flex-wrap:wrap;gap:7px}.tools button,.count button,.tabs button{padding:7px 10px;border:1px solid var(--vp-c-divider);border-radius:99px;background:transparent;color:var(--vp-c-text-2);cursor:pointer;font:inherit;font-size:.82rem}.tools button:hover{border-color:var(--vp-c-brand-1);color:var(--vp-c-brand-1)}.tools button:focus-visible{outline:2px solid color-mix(in srgb,var(--vp-c-brand-1) 45%,transparent);outline-offset:2px}.tools button.on,.tabs button.on{border-color:var(--vp-c-brand-1);background:color-mix(in srgb,var(--vp-c-brand-1) 15%,transparent);color:var(--vp-c-brand-1)}.filter-group>div>button:first-child.on{border-color:color-mix(in srgb,var(--vp-c-brand-1) 55%,var(--vp-c-divider));background:color-mix(in srgb,var(--vp-c-brand-1) 10%,transparent);color:var(--vp-c-brand-1);font-weight:500}.filter-group>div>button:not(:first-child).on{border-color:var(--vp-c-brand-1);background:color-mix(in srgb,var(--vp-c-brand-1) 18%,transparent)